1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import { randomUUID } from 'node:crypto';
6	import {
7	  FIELD_LIMITS,
8	  checkIdeaContent,
9	  normalizeIdea,
10	  fieldRulesBrowserScript,
11	  type ContentErrorCode,
12	} from './idea-fields.ts';
13	
14	const PRODUCT: string = 'FeatureHarbor';
15	const RESOURCE: string = 'ideas';
16	const MAX_BODY_BYTES = 1_000_000;
17	// 接口侧把共用的内容判定结果映射成原有的错误说明；首页另有自己的措辞。
18	const CONTENT_ERROR_MESSAGES: Record<ContentErrorCode, string> = {
19	  'title-empty': '标题去掉首尾空白后不能为空',
20	  'title-too-long': `标题最多 ${FIELD_LIMITS.title} 个字符`,
21	  'description-empty': '详细说明必须包含非空白内容',
22	  'description-too-long': `详细说明最多 ${FIELD_LIMITS.description} 个字符`,
23	  'scenario-too-long': `使用场景最多 ${FIELD_LIMITS.scenario} 个字符`,
24	};
25	const PAGE: string = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FeatureHarbor · 产品意见与公开路线图</title><style>
26	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
27	a{color:#175b9c}
28	label{display:block;font-weight:600;margin-top:1rem}
29	input,textarea{width:100%;box-sizing:border-box;padding:.4rem;font:inherit}
30	textarea{resize:vertical}
31	.required{color:#b00020}
32	button{margin-top:1rem;padding:.5rem 1.2rem;font:inherit}
33	#error{color:#b00020;margin-top:.75rem}
34	#success{color:#1a7f37;margin-top:.75rem}
35	.idea{border-top:1px solid #ddd;padding:1rem 0}
36	.idea h3{margin:0 0 .5rem}
37	.pre{white-space:pre-wrap}
38	time{color:#666;font-size:.9rem}
39	</style><main><h1>FeatureHarbor</h1><p>产品意见与公开路线图</p>
40	<h2>提交产品意见</h2>
41	<form id="idea-form" novalidate>
42	<label for="f-title">标题 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.title} 字）</label>
43	<input id="f-title" name="title" required>
44	<label for="f-desc">详细说明 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.description} 字）</label>
45	<textarea id="f-desc" name="description" rows="5" required></textarea>
46	<label for="f-scenario">使用场景（可选，最多 ${FIELD_LIMITS.scenario} 字）</label>
47	<textarea id="f-scenario" name="scenario" rows="3"></textarea>
48	<button type="submit">提交意见</button>
49	<p id="error" role="alert" hidden></p>
50	<p id="success" role="status" hidden></p>
51	</form>
52	<h2>意见列表</h2>
53	<p id="empty" hidden>还没有意见记录。</p>
54	<div id="ideas"></div>
55	<p><a href="/api/ideas">查看意见列表接口</a> · <a href="/health">服务状态</a></p>
56	</main><script>
57	${fieldRulesBrowserScript}
58	const form = document.getElementById('idea-form');
59	const titleInput = document.getElementById('f-title');
60	const descInput = document.getElementById('f-desc');
61	const scenarioInput = document.getElementById('f-scenario');
62	const errorBox = document.getElementById('error');
63	const successBox = document.getElementById('success');
64	const emptyNote = document.getElementById('empty');
65	const list = document.getElementById('ideas');
66	const EMPTY_TEXT = '还没有意见记录。';
67	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
68	// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
69	let listState = 'loading';
70	function showError(message) {
71	  errorBox.textContent = message;
72	  errorBox.hidden = false;
73	  successBox.hidden = true;
74	}
75	function renderIdea(idea) {
76	  const item = document.createElement('article');
77	  item.className = 'idea';
78	  const heading = document.createElement('h3');
79	  heading.textContent = idea.title;
80	  const desc = document.createElement('p');
81	  desc.className = 'pre';
82	  desc.textContent = idea.description;
83	  item.append(heading, desc);
84	  if (typeof idea.scenario === 'string' && idea.scenario.trim().length > 0) {
85	    const scenario = document.createElement('p');
86	    const label = document.createElement('strong');
87	    label.textContent = '使用场景：';
88	    const text = document.createElement('span');
89	    text.className = 'pre';
90	    text.textContent = idea.scenario;
91	    scenario.append(label, text);
92	    item.append(scenario);
93	  }
94	  const time = document.createElement('time');
95	  time.dateTime = idea.createdAt;
96	  const parsed = new Date(idea.createdAt);
97	  time.textContent = isNaN(parsed.getTime()) ? String(idea.createdAt) : parsed.toLocaleString();
98	  item.append(time);
99	  return item;
100	}
101	let remoteIdeas = [];
102	// 本页已确认保存的意见，按本页发起提交的先后排列：后提交的在前。
103	// 每条记录带上点击提交时的序号，响应返回的先后不影响排列位置
104	const submittedIdeas = [];
105	function renderList() {
106	  // 以服务端标识 id 去重后合并：本页提交成功的意见在前，其后补入首次响应中的其他记录
107	  const seen = new Set();
108	  const ordered = [];
109	  for (const entry of submittedIdeas) {
110	    const idea = entry.idea;
111	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
112	  }
113	  for (const idea of remoteIdeas) {
114	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
115	  }
116	  list.replaceChildren(...ordered.map(renderIdea));
117	  if (listState === 'failed') {
118	    emptyNote.textContent = LOAD_FAILED_TEXT;
119	    emptyNote.hidden = false;
120	  } else if (listState === 'ready') {
121	    emptyNote.textContent = EMPTY_TEXT;
122	    emptyNote.hidden = ordered.length > 0;
123	  } else {
124	    // 首次列表仍在加载，不能把等待误报成没有记录
125	    emptyNote.hidden = true;
126	  }
127	}
128	// 一条有效意见必须是 JSON 对象：id 为非空字符串，
129	// title、description、scenario、createdAt 均为字符串（scenario 允许为空字符串）
130	function isValidIdea(idea) {
131	  if (typeof idea !== 'object' || idea === null || Array.isArray(idea)) return false;
132	  if (typeof idea.id !== 'string' || idea.id.length === 0) return false;
133	  for (const field of ['title', 'description', 'scenario', 'createdAt']) {
134	    if (typeof idea[field] !== 'string') return false;
135	  }
136	  return true;
137	}
138	async function loadIdeas() {
139	  try {
140	    const res = await fetch('/api/ideas');
141	    if (!res.ok) throw new Error('load failed');
142	    const data = await res.json();
143	    // 列表响应必须是带 ideas 数组的 JSON 对象，且数组中每条记录都合法；
144	    // 顶层结构异常或任意一条记录异常都属于整次加载失败，
145	    // 即使异常记录前面有正常意见，也不能只展示其中一部分
146	    if (typeof data !== 'object' || data === null || Array.isArray(data) || !Array.isArray(data.ideas)) {
147	      throw new Error('invalid ideas response');
148	    }
149	    if (!data.ideas.every(isValidIdea)) throw new Error('invalid idea record');
150	    remoteIdeas = data.ideas;
151	    listState = 'ready';
152	  } catch {
153	    listState = 'failed';
154	  }
155	  renderList();
156	}
157	// 任一字段每次发生编辑都递增；提交时记下当前版本，成功响应到达时若版本未变，
158	// 说明等待期间没有继续编辑，才清空表单，否则保留正在写的草稿
159	let editVersion = 0;
160	for (const field of [titleInput, descInput, scenarioInput]) {
161	  field.addEventListener('input', () => { editVersion += 1; });
162	}
163	// 字段内容判定与接口共用同一份实现（FIELD_LIMITS、codePointCount、checkIdeaContent
164	// 由 idea-fields.ts 注入）；这里只把共用判定结果映射成本页原有的提示措辞与顺序。
165	function validate(title, description, scenario) {
166	  switch (checkIdeaContent(title, description, scenario)) {
167	    case 'title-empty': return '标题不能为空。';
168	    case 'title-too-long': return '标题最多 ' + FIELD_LIMITS.title + ' 个字符。';
169	    case 'description-empty': return '详细说明不能为空。';
170	    case 'description-too-long': return '详细说明最多 ' + FIELD_LIMITS.description + ' 个字符。';
171	    case 'scenario-too-long': return '使用场景最多 ' + FIELD_LIMITS.scenario + ' 个字符。';
172	    default: return null;
173	  }
174	}
175	// 每次点击提交都递增：成功或失败提示只属于最近一次点击。
176	// 更早发出的请求即使更晚返回，也只能在服务确认保存时更新列表，不能改动当前提示。
177	let latestSubmitSeq = 0;
178	form.addEventListener('submit', async (event) => {
179	  event.preventDefault();
180	  const submitSeq = ++latestSubmitSeq;
181	  // 用户发起新的提交后，上一条操作的提示先清除；在本次点击有结果前，
182	  // 更早请求迟到返回也不能重新显示成功或失败，也不能让人误以为正在提交的意见已保存
183	  errorBox.hidden = true;
184	  successBox.hidden = true;
185	  const title = titleInput.value;
186	  const description = descInput.value;
187	  const scenario = scenarioInput.value;
188	  const submittedVersion = editVersion;
189	  const problem = validate(title, description, scenario);
190	  // 被表单直接拦下的一次点击同样是用户最近的提交操作，字段错误即本次点击的结果；
191	  // 之后更早请求的返回不能掩盖它
192	  if (problem) { showError(problem); return; }
193	  let res;
194	  try {
195	    res = await fetch('/api/ideas', {
196	      method: 'POST',
197	      headers: { 'content-type': 'application/json' },
198	      body: JSON.stringify({ title, description, scenario })
199	    });
200	  } catch {
201	    if (submitSeq === latestSubmitSeq) showError('网络错误，提交未成功，请重试。');
202	    return;
203	  }
204	  let data = null;
205	  try { data = await res.json(); } catch { data = null; }
206	  if (!res.ok) {
207	    if (submitSeq === latestSubmitSeq) {
208	      showError(data && data.error ? '提交失败：' + data.error : '提交失败，请稍后重试。');
209	    }
210	    return;
211	  }
212	  // 成功状态的响应同样必须结构完整：顶层是含 idea 的 JSON 对象，
213	  // 且 idea 本身通过 isValidIdea 校验（对象、非空 id、各字段均为字符串）。
214	  // 空对象、数组或缺字段的记录不能当作保存成功：不显示成功提示、
215	  // 不清空草稿、不并入列表，也不用表单内容补齐响应缺失的信息
216	  const saved = typeof data === 'object' && data !== null && !Array.isArray(data) && isValidIdea(data.idea);
217	  if (!saved) {
218	    if (submitSeq === latestSubmitSeq) showError('提交失败，请稍后重试。');
219	    return;
220	  }
221	  const idea = data.idea;
222	  // 是否清空表单只取决于等待期间有没有继续编辑（包括改回原文、清空字段也算编辑），
223	  // 与响应返回先后无关：过期请求确认保存时也不能清掉用户正在写的草稿
224	  if (editVersion === submittedVersion) form.reset();
225	  // 只要服务确认保存，意见就进入列表，即使这条请求已不是最近一次点击：
226	  // 不能为了避免提示干扰而丢弃真实保存结果。
227	  // 位置按本页发起提交的先后确定（后提交的在前），与响应返回先后无关：
228	  // 先提交的意见迟到确认时补到后提交的意见之后，不能把它挤到更靠后的位置
229	  const entry = { seq: submitSeq, idea };
230	  let insertAt = submittedIdeas.findIndex((e) => e.seq < submitSeq);
231	  if (insertAt === -1) insertAt = submittedIdeas.length;
232	  submittedIdeas.splice(insertAt, 0, entry);
233	  renderList();
234	  // 成功提示只属于最近一次点击：更早的请求迟到返回时，不能在最新一次的失败提示
235	  // 或新一次提交的等待旁边再显示成功
236	  if (submitSeq === latestSubmitSeq) {
237	    successBox.textContent = '提交成功，你的意见已保存。';
238	    successBox.hidden = false;
239	  }
240	});
241	loadIdeas();
242	</script></html>`;
243	const args: string[] = process.argv.slice(2);
244	const help: string = `FeatureHarbor - 产品意见与公开路线图
