282	// title、description、scenario、createdAt 均存在且为字符串（scenario 允许为空字符串）。
283	// 这里只检查历史记录的结构完整性，不套用新提交的内容限制：
284	// 标题首尾空白、正文与场景换行、任意时间字符串都按原样保留，不补字段或改写文字。
285	function isStoredIdea(record: unknown): boolean {
286	  if (typeof record !== 'object' || record === null || Array.isArray(record)) return false;
287	  const idea = record as Record<string, unknown>;
288	  if (typeof idea.id !== 'string' || idea.id.length === 0) return false;
289	  for (const field of ['title', 'description', 'scenario', 'createdAt'] as const) {
