322	  } catch {
323	    respond(res, 400, { error: '请求体不是有效的 JSON' });
324	    return;
325	  }
326	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
327	    respond(res, 400, { error: '请求体必须是 JSON 对象' });
328	    return;
329	  }
330	  const body = payload as Record<string, unknown>;
331	  for (const field of ['title', 'description'] as const) {
332	    if (body[field] === undefined) { respond(res, 400, { error: `缺少必填字段 ${field}` }); return; }
333	    if (typeof body[field] !== 'string') { respond(res, 400, { error: `字段 ${field} 必须是字符串` }); return; }
334	  }
335	  if (body.scenario !== undefined && typeof body.scenario !== 'string') {
336	    respond(res, 400, { error: '字段 scenario 必须是字符串' });
337	    return;
338	  }
339	  const rawTitle = body.title as string;
340	  const rawDescription = body.description as string;
341	  const scenario = typeof body.scenario === 'string' ? body.scenario : '';
342	  // 内容规则（空白与上限）与首页共用同一份判定，这里只保留接口原有的错误措辞。
343	  const problem = checkIdeaContent(rawTitle, rawDescription, scenario);
344	  if (problem) {
345	    respond(res, 400, { error: CONTENT_ERROR_MESSAGES[problem] });
346	    return;
347	  }
